    for idx in range(target_len):
        start = math.floor(idx * seq_len / target_len)
        end = max(start + 1, math.floor((idx + 1) * seq_len / target_len))
        pooled_mask[:, idx] = mask[:, start:end].any(dim=1)
    return ensure_non_empty_mask(pooled_mask)


